from taf.ul.ettf.utils.tjellyfish import ITJellyfishRemoteCommand


class TcpDump(ITJellyfishRemoteCommand):
    def __init__(self):
        self._cmd = ['tcpdump']

    @property
    def cmd(self):
        return ' '.join(self._cmd)

    def buffered_packets(self):
        self._cmd.append('-U')
        return self

    def dont_convert_addresses(self):
        self._cmd.append('-n')
        return self

    def set_snaplen(self, snaplen):
        self._cmd.extend(['-s', str(snaplen)])
        return self

    def set_interface(self, *interface):
        self._cmd.append('-i')
        self._cmd.extend(interface)
        return self

    def set_input_file(self, input_path):
        self._cmd.extend(['-r', input_path])
        return self

    def set_output_file(self, output_file):
        self._cmd.extend(['-w', output_file])
        return self

    def set_filter(self, tshark_filter):
        self._cmd.extend(['-Y', tshark_filter])
        return self

    def read_from_std(self):
        self.set_input_file('-')
        return self

    def write_to_std(self):
        self.set_output_file('-')
        return self
